const voltraBiomeThemes={cherry:{accent:'#ff55c8',bg:'#2b123d',native:'cherry'},purple:{accent:'#9278ff',bg:'#171326',native:'purple'},forest:{accent:'#59e66e',bg:'#092a1d',native:'forest'},winter:{accent:'#59c9ff',bg:'#0b1c3a',native:'winter'},nether:{accent:'#ff4141',bg:'#300a12',native:'nether'},ocean:{accent:'#20d8ff',bg:'#08262d',native:'ocean'},desert:{accent:'#ffb52e',bg:'#4a2308',native:'desert'},end:{accent:'#c45bff',bg:'#210b3a',native:'end'},mountains:{accent:'#dce8ff',bg:'#15233a',native:'mountains'},swamp:{accent:'#c5d66c',bg:'#182516',native:'swamp'}};function applyBiomeIconTheme(theme,notify){const t=voltraBiomeThemes[theme]?theme:'cherry',v=voltraBiomeThemes[t];try{localStorage.setItem('voltraBiomeIconTheme',t);localStorage.setItem('pulseAccent',v.accent);localStorage.setItem('pulseChatBg',v.bg)}catch{}const sel=$('settingBiomeIcon');if(sel)sel.value=t;document.documentElement.style.setProperty('--accent',v.accent);document.documentElement.style.setProperty('--custom-chat-bg',v.bg);document.body.classList.add('custom-chat-background');if(window.VOLTRA_NATIVE?.setLauncherIcon)window.VOLTRA_NATIVE.setLauncherIcon(v.native);if(notify)toast('Тема биома включена ✨')}function applyPersonalAppIcon(){const data=localStorage.getItem('voltraPersonalIcon')||'';let link=document.querySelector('link[data-personal-icon]');if(!link){link=document.createElement('link');link.rel='icon';link.dataset.personalIcon='1';document.head.append(link)}link.href=data||'/icon.svg';const p=$('appIconPreview');if(p)p.innerHTML=data?'<img alt="Моя иконка" src="'+data+'">':'V'}function readPersonalAppIcon(file){if(!file)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type)){toast('Выбери PNG, JPG или WEBP');return}if(file.size>8*1024*1024){toast('Изображение должно быть меньше 8 МБ');return}const reader=new FileReader();reader.onerror=()=>toast('Не удалось прочитать изображение');reader.onload=()=>{const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');canvas.width=128;canvas.height=128;ctx.clearRect(0,0,128,128);const scale=Math.min(128/img.width,128/img.height),w=img.width*scale,h=img.height*scale;ctx.drawImage(img,(128-w)/2,(128-h)/2,w,h);const data=canvas.toDataURL('image/png');try{localStorage.setItem('voltraPersonalIcon',data);applyPersonalAppIcon();toast('Иконка вкладки обновлена 📱')}catch{toast('Не удалось сохранить иконку: освободи место в хранилище браузера')}};img.onerror=()=>toast('Не удалось открыть изображение');img.src=String(reader.result||'')};reader.readAsDataURL(file)}function formatLastSeen(user){if(!user)return 'Не в сети';if(user.online)return 'В сети';const value=Number(user.lastSeen);if(!Number.isFinite(value)||value<=0)return 'Не в сети';const diff=Math.max(0,Date.now()-value);if(diff<60000)return 'был(а) в сети только что';if(diff<3600000)return 'был(а) в сети '+Math.floor(diff/60000)+' мин. назад';if(diff<86400000)return 'был(а) в сети '+Math.floor(diff/3600000)+' ч. назад';const d=new Date(value),now=new Date();if(d.toDateString()===now.toDateString())return 'был(а) в сети сегодня в '+d.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});const yesterday=new Date(now);yesterday.setDate(now.getDate()-1);if(d.toDateString()===yesterday.toDateString())return 'был(а) в сети вчера в '+d.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});return 'был(а) в сети '+d.toLocaleDateString([], {day:'numeric',month:'short'})+' в '+d.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}
