async function authenticate(){
 const name=$('nickname').value.trim(),password=$('password').value;
 // A stale WebSocket created by the initial cookie check can still be CONNECTING; clear it before fetching a fresh one-time ticket.
 if(!myId&&ws){const oldSocket=ws;ws=null;oldSocket.onclose=null;oldSocket.onerror=null;try{oldSocket.close(1000,'Refreshing authentication')}catch{}}
 window.__voltraAuthAttempting=true;
 beginAuthRestore(authMode==='login'?'Входим в VOLTRA':'Создаём аккаунт','Проверяем данные и подключаем твои чаты…');
 $('authSubmit').disabled=true;$('loginError').textContent=authMode==='login'?'Входим…':'';
 try{
  if(authMode==='register'){
   const r=await fetch('/api/register',{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',body:JSON.stringify({name,password,ref:new URLSearchParams(location.search).get('ref')||''})});
   const d=await r.json();if(!r.ok)throw new Error(d.error||'Не удалось создать аккаунт');
   myName=d.user.name;myUsername=d.user.username||'';wsAuthTicket=d.wsTicket||'';try{localStorage.setItem('pulseLastAccount',myName)}catch{}connect();return;
  }
  const r=await fetch('/api/login',{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',body:JSON.stringify({name,password})});
  const data=await r.json();if(!r.ok)throw new Error(data.error||'Не удалось выполнить запрос');
  myName=data.user.name;myUsername=data.user.username||'';wsAuthTicket=data.wsTicket||'';try{localStorage.setItem('pulseLastAccount',myName)}catch{}connect();
 }catch(e){window.__voltraAuthAttempting=false;window.__voltraAutoLoginWaiting=false;window.__voltraManualLoginReady=true;authRestoreInProgress=false;finishAuthSplash();$('login')?.classList.remove('hidden');$('loginError').textContent=e.message||'Ошибка соединения'}finally{$('authSubmit').disabled=false}
}
function showAuthSplash(title,subtitle){
 const splash=$('bootLoader');
 if(!splash)return;
 const heading=$('bootLoaderTitle'),copy=$('bootLoaderSubtitle');
 if(heading&&title)heading.textContent=title;
 if(copy&&subtitle)copy.textContent=subtitle;
 splash.classList.remove('hidden');
}
function finishAuthSplash(){
 clearTimeout(authRestoreWatchdog);
 authRestoreWatchdog=null;
 // Once authenticated, keep the premium splash visible long enough to read two tips.
 if(window.__voltraAuthed===true){
  const started=Number(window.__voltraLoaderStartedAt)||Date.now();
  const minimumUntil=started+8300;
  const shown=Number(window.__voltraTipsShownThisLoad)||0;
  if(Date.now()<minimumUntil||shown<2){
   if(!window.__voltraLoaderFinishTimer)window.__voltraLoaderFinishTimer=setTimeout(()=>{window.__voltraLoaderFinishTimer=null;finishAuthSplash()},Math.max(250,Math.min(900,minimumUntil-Date.now()>0?minimumUntil-Date.now():500)));
   return;
  }
 }
 clearTimeout(window.__voltraLoaderFinishTimer);
 window.__voltraLoaderFinishTimer=null;
 $('bootLoader')?.classList.add('hidden');
}
function beginAuthRestore(title,subtitle){
 authRestoreInProgress=true;
 window.__voltraAuthAttempting=true;
 window.__voltraManualLoginReady=false;
 showAuthSplash(title,subtitle);
 clearTimeout(authRestoreWatchdog);
 authRestoreWatchdog=setTimeout(()=>{
  if(myId)return;
  window.__voltraAuthAttempting=false;
  authRestoreInProgress=false;
  finishAuthSplash();
  $('login')?.classList.remove('hidden');
  if(!$('loginError')?.textContent) $('loginError').textContent='Не получилось восстановить вход автоматически. Нажми «Войти» ещё раз.';
 },9000);
}
async function checkSession(){
 // Keep the animated VOLTRA splash visible while Chrome finishes password autofill.
 window.__voltraAutoLoginWaiting=true;
 window.__voltraManualLoginReady=false;
 showAuthSplash('Возвращаем тебя в VOLTRA','Проверяем сохранённую сессию и подключаем чаты…');
 try{
  const authCheckController=new AbortController();
  const authCheckTimer=setTimeout(()=>authCheckController.abort(),4500);
  let r;
  try{r=await fetch('/api/me',{credentials:'same-origin',cache:'no-store',signal:authCheckController.signal})}
  finally{clearTimeout(authCheckTimer)}
  if(r.ok){
   const d=await r.json();
   myName=d.user.name;myUsername=d.user.username||'';wsAuthTicket=d.wsTicket||'';
   try{localStorage.setItem('pulseLastAccount',myName)}catch{}
   window.__voltraAutoLoginWaiting=false;
   beginAuthRestore('Возвращаем тебя в VOLTRA','Проверяем сохранённую сессию и подключаем чаты…');
   connect();
   return;
  }
 }catch{}
 // Password managers may autofill noticeably later than the first page render.
 // Poll long enough, without exposing the form over the animated splash.
 let tries=0,started=false;
 const revealForm=()=>{
  if(started||myId)return;
  window.__voltraAutoLoginWaiting=false;
  window.__voltraManualLoginReady=true;
  finishAuthSplash();
  $('login')?.classList.remove('hidden');
 };
 const tryAutoLogin=()=>{
  if(started||myId)return;
  tries++;
  const name=$('nickname')?.value.trim()||'',password=$('password')?.value||'';
  if(authMode==='login'&&name.length>=3&&password.length>=8){
   started=true;autoLoginAttempted=true;
   window.__voltraAutoLoginWaiting=false;
   window.__voltraManualLoginReady=false;
   beginAuthRestore('Входим автоматически','Используем сохранённые данные браузера…');
   // Use the same auth handler as the button, keeping the splash above the form.
   authenticate();
   return;
  }
  if(tries<20)setTimeout(tryAutoLogin,500);
  else revealForm();
 };
 setTimeout(tryAutoLogin,250);
}
async function requestPushPermissionOnEntry(){
 if(!myId||!('Notification'in window)||!('serviceWorker'in navigator)||!('PushManager'in window))return;
 if(Notification.permission!=='default')return;
 try{
  const permission=await Notification.requestPermission();
  if(permission!=='granted')return;
  const reg=await navigator.serviceWorker.register('/sw.js');let sub=await reg.pushManager.getSubscription();
  if(sub)return;
  const kr=await fetch('/api/push/public-key',{credentials:'same-origin'}),kd=await kr.json();if(!kr.ok||!kd.publicKey)return;
  sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlBase64ToBytes(kd.publicKey)});
  const r=await fetch('/api/push/subscribe',{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',body:JSON.stringify({subscription:sub.toJSON()})});if(!r.ok)await sub.unsubscribe();else{updatePushButton();toast('Пуш-уведомления включены 🔔')}
 }catch(e){console.warn('Push permission on entry:',e)}
}
