function renderList(){
 renderChatFolders();
 const rawQuery=$('search').value.trim().toLowerCase(),q=rawQuery.replace(/^@/,''),el=$('chatList');el.innerHTML='';if(rawQuery.length>=1)searchDirectory(rawQuery);
 if(tab==='channels'){const list=channels.filter(c=>(c.isMember||c.isOwner||c.owner==='system')&&(c.name.toLowerCase().includes(q)||String(c.description).toLowerCase().includes(q)));if(!list.length)el.innerHTML='<div class="muted" style="padding:16px">Пока нет каналов. Создай первый через «＋ Канал / группа».</div>';list.forEach(c=>el.append(makeListItem({id:'channel:'+c.id,name:(c.type==='group'?'👥 ':'📣 ')+c.name,subtitle:c.description||(c.type==='group'?'Группа':'Канал')})));return}
 if(tab==='news'){el.innerHTML='<div class="news-create-wrap" style="padding:10px 12px"><button type="button" class="primary" data-open-news-composer style="width:100%;padding:12px;border-radius:12px">✍ Создать новость</button></div>';if(!newsPosts.length)el.insertAdjacentHTML('beforeend','<div class="muted" style="padding:16px">Пока новостей нет.</div>');newsPosts.filter(p=>(p.title+' '+p.body).toLowerCase().includes(q)).forEach(p=>{const n=document.createElement('div');n.className='news-item';const reactions=p.reactions||{},buttons=['❤️','😂','🔥','👍','👏','😮'].map(em=>{const ids=reactions[em]||[];return '<button class="post-reaction '+(ids.includes(myId)?'active':'')+'" data-post-react="'+esc(p.id)+'" data-post-emoji="'+em+'">'+em+' <small>'+ids.length+'</small></button>'}).join('');n.innerHTML='<b>'+esc(p.title)+'</b><p>'+esc(p.body)+'</p><small>'+esc(p.author||'VOLTRA News')+' · '+new Date(p.at).toLocaleString()+'</small>'+(p.link?'<p><a target="_blank" rel="noopener" href="'+esc(p.link)+'">Открыть ссылку ↗</a></p>':'')+'<div class="post-reactions">'+buttons+'</div>';el.append(n)});return}
 if(tab==='chats'){
  const favs=readFavorites();const self=users.find(u=>u.id===myId),all=[{id:'favorites',name:'⭐ Избранное',subtitle:favs.length?(favs.at(-1).text||favs.at(-1).attachment?.name||'Вложения сохранены'):'Личный чат · только у тебя',group:true},...(self?.globalChatDisabled?[]:[{id:globalKey,name:'Общий чат',subtitle:'Общение со всеми пользователями',group:true},{id:'cookie-bot',name:'🍪 Печенька',subtitle:'Кликай: 30 кликов = 1 Вольтрикс',group:true}])];all.push({id:'crypto-bot',name:'🐱 Крипто бот',subtitle:'Кошелёк CAT · обмен и переводы',group:true});if(self?.globalChatDisabled)el.innerHTML='<div class="muted" style="padding:16px">🔒 Доступ к общему чату отключён администратором.</div>';
  [...new Map([...users,...readAddedDirectoryContacts()].filter(u=>u.id!==myId).map(u=>[u.id,u])).values()].forEach(u=>{const has=messagesByChat.has(dmKey(u.id)),added=readAddedDirectoryContacts().some(x=>x.id===u.id);all.push({id:u.id,name:u.name,subtitle:has?lastText(messagesByChat.get(dmKey(u.id)).at(-1)):(added?'@'+(u.username||'user')+' · Добавлен в чаты':'История переписки · нажми, чтобы открыть')})});
  (window.pulseMiniApps||[]).filter(x=>(((window.pulseSubscribedBotIds||[]).includes(x.id))||readAddedBots().includes(x.id))&&(x.botName+' '+x.name).toLowerCase().includes(q)).forEach(x=>all.push({id:'mini-bot:'+x.id,name:x.botName,subtitle:'🤖 Бот · '+x.name,group:true}));
  const visible=all.filter(x=>{const name=String(x.name||'').toLowerCase(),subtitle=String(x.subtitle||'').toLowerCase(),key=x.id===globalKey?globalKey:(String(x.id).startsWith('channel:')?channelKey(String(x.id).slice(8)):dmKey(x.id)),unread=unreadCounts.get(key)||0,isBot=String(x.id).startsWith('mini-bot:')||x.id==='cookie-bot'||x.id==='crypto-bot',isSpecial=['favorites',globalKey,'cookie-bot','crypto-bot'].includes(x.id)||isBot,isPersonal=!isSpecial&&x.id!==myId;const folderMatch=chatFolder==='all'||(chatFolder==='unread'&&unread>0)||(chatFolder==='private'&&isPersonal)||(chatFolder==='bots'&&isBot)||(chatFolder==='favorites'&&x.id==='favorites');return folderMatch&&(name.includes(q)||subtitle.includes(q))});if(!visible.length)el.innerHTML='<div class="muted folder-empty">'+(chatFolder==='unread'?'🎉 Непрочитанных чатов нет':chatFolder==='private'?'Личные переписки появятся здесь':chatFolder==='bots'?'Боты появятся здесь':chatFolder==='favorites'?'Избранное пока пустое':'Ничего не найдено')+'</div>';visible.sort((a,b)=>Number(!!chatPreference(b.id).pinned)-Number(!!chatPreference(a.id).pinned));visible.forEach(x=>el.append(makeListItem(x)));
 }else{
  const found=[...new Map([...users,...readAddedDirectoryContacts()].filter(u=>u.id!==myId).map(u=>[u.id,u])).values()].filter(u=>!q||u.name.toLowerCase().includes(q)||String(u.username||'').toLowerCase().includes(q));if(!found.length)el.innerHTML='<div class="muted" style="padding:16px">'+(q?'Ищем по нику и @юзернейму…':'Здесь показываются существующие переписки. Новых людей ищи по @юзернейму.')+'</div>';found.forEach(u=>el.append(makeListItem({id:u.id,name:u.name,subtitle:'@'+(u.username||'user')+' · '+(u.online?'В сети':'Не в сети')})));
 }
}
window.addEventListener('pulse-miniapps-updated',()=>{renderList();if(String(activeId||'').startsWith('mini-bot:'))renderMessages()});
function lastText(m){if(!m)return'Пока нет сообщений';if(m.text==='VOLTRA_PRANK::dox')return'⚠️ Симуляция сбора данных · пранк';if(m.text==='VOLTRA_PRANK::snos')return'⏳ Симуляция сноса · пранк';if(m.text)return m.text;const count=(m.attachments||[]).length+(m.attachment?1:0);if(count>1)return '🖼️ Альбом · '+count+' файла';return ((m.attachment?.mime||m.attachments?.[0]?.mime||'').startsWith('image/')?'📷 Фото':((m.attachment?.mime||'').startsWith('video/')?'🎬 Видео':'📎 Файл'))}
function makeListItem(x){
 const b=document.createElement('div');
 b.dataset.chatItemId=String(x.id);
 b.className='chat-item'+(activeId===x.id?' active':'');
 const key=x.id===globalKey?globalKey:(String(x.id).startsWith('channel:')?channelKey(String(x.id).slice(8)):dmKey(x.id));
 const unread=unreadCounts.get(key)||0;
 const person=users.find(u=>u.id===x.id)||(window.pulseDirectoryUsers||[]).find(u=>u.id===x.id)||readAddedDirectoryContacts().find(u=>u.id===x.id);
 const baseShownName=person?labelFor(x.id):x.name;const rawThinkName=[person?.name,person?.username,person?.roleLabel].filter(Boolean).join(' ').toLocaleLowerCase('ru-RU').replace(/ё/g,'е');const isThinkUser=rawThinkName.includes('думайте')||rawThinkName.includes('дкмайте')||rawThinkName.includes('заставляет задуматься');const shownName=isThinkUser?(person?.name||baseShownName):baseShownName;
 const miniBot=String(x.id).startsWith('mini-bot:');
 const miniApp=miniBot?[...((window.pulseMiniApps)||[]),...((window.pulseDirectoryApps)||[])].find(v=>v.id===String(x.id).slice(9)):null;
 const onlineClass=x.group?'':(users.some(u=>u.id===x.id&&u.online)?' online':'');
 let icon;
 if(x.id==='cookie-bot') icon='🍪';
 else if(x.id==='crypto-bot') icon='🐱';
 else if(miniBot) icon=miniApp?.botImageUrl?'<img class="avatar-image" src="'+esc(miniApp.botImageUrl)+'" alt="">':esc(miniApp?.botIcon||'🤖');
 else if(x.group) icon='✦';
 else icon=avatarContent(shownName,person?.avatar);
 b.innerHTML='<div class="avatar">'+icon+'</div><div class="chat-preview"><div class="chat-meta"><b>'+esc(shownName)+easterEggDecor({...person,name:shownName})+(isThinkUser?vipBadge(person):adminBadge(person))+giftDecor(person)+'</b><span class="presence-badge'+onlineClass+'"></span></div><small>'+esc(x.subtitle)+'</small></div>'+(unread?'<span class="unread-badge">'+(unread>99?'99+':unread)+'</span>':'');
 b.onclick=()=>openChat(x.id);
 return b;
}
function showEmpty(){$('welcome').classList.remove('hidden');$('messages').classList.add('hidden');$('composer').classList.add('hidden');$('peerName').textContent='Выбери чат';$('peerStatus').textContent='Твои сообщения — здесь';$('peerAvatar').textContent='P';renderList()}
window.pulseOpenMiniBot=id=>openChat('mini-bot:'+id);

function voltraSlug(value){return String(value||'').normalize('NFKD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase().replace(/[^a-z0-9_ -]/g,'').trim().replace(/[ _]+/g,'-').replace(/-+/g,'-').replace(/^-|-$/g,'').slice(0,48)||'voltra'}
function voltraLinkForChat(id){
 const key=String(id||'');
 if(key.startsWith('mini-bot:')){const bot=(window.pulseMiniApps||[]).find(x=>String(x.id)===key.slice(9));return location.origin+'/bot/'+voltraSlug(bot?.botName||bot?.name||key.slice(9))}
 if(key.startsWith('channel:')){const channel=channels.find(x=>String(x.id)===key.slice(8));return location.origin+'/channel/'+voltraSlug(channel?.name||key.slice(8))}
 if(key==='cookie-bot')return location.origin+'/bot/pechenka';
 if(key==='crypto-bot')return location.origin+'/bot/kripto-bot';
 if(key==='favorites')return location.origin+'/settings/favorites';
 if(key===globalKey)return location.origin+'/chat/general';
 const peer=users.find(u=>String(u.id)===key)||readAddedDirectoryContacts().find(u=>String(u.id)===key)||(window.pulseDirectoryUsers||[]).find(u=>String(u.id)===key);
 const username=String(peer?.username||'').replace(/^@/,'').trim();
 return username?location.origin+'/'+encodeURIComponent(username):location.origin+'/chat/'+voltraSlug(peer?.name||key);
}
async function voltraCopyLink(url){try{await navigator.clipboard.writeText(url);toast('Ссылка скопирована: '+url)}catch{prompt('Скопируй ссылку:',url)}}
function voltraRouteForCurrent(){const path=location.pathname.split('/').filter(Boolean);return path.length?path:null}
function voltraResolveDeepLink(){
 const parts=location.pathname.split('/').filter(Boolean).map(decodeURIComponent);if(!parts.length)return;
 if(!window.currentUser&&!window.pulseCurrentUser&&!(typeof myUsername!=='undefined'&&myUsername)){try{sessionStorage.setItem('voltraPendingDeepLink',location.pathname)}catch{}return}
 if(parts[0]==='gift'&&parts[1]){if(typeof window.pulseOpenGiftBySlugOrId==='function')window.pulseOpenGiftBySlugOrId(parts[1]).catch(e=>console.warn('Gift deep link failed:',e));else try{sessionStorage.setItem('voltraPendingDeepLink',location.pathname)}catch{}return}
 if(parts[0]==='settings'){showModal('settingsModal');return}
 if(parts[0]==='chat'&&parts[1]==='general'){openChat(globalKey);return}
 if(parts[0]==='bot'&&parts[1]){const wanted=voltraSlug(parts.slice(1).join('/'));if(wanted==='pechenka'){openChat('cookie-bot');return}if(wanted==='kripto-bot'){openChat('crypto-bot');return}
  const app=(window.pulseMiniApps||[]).find(x=>voltraSlug(x.botName||x.name||x.id)===wanted);if(app){openChat('mini-bot:'+app.id);return}
 }
 if(parts[0]==='channel'&&parts[1]){const c=channels.find(x=>voltraSlug(x.name)===voltraSlug(parts.slice(1).join('/')));if(c){openChat('channel:'+c.id);return}}
 if(parts.length===1){const wanted=parts[0].replace(/^@/,'').toLowerCase();const peer=users.find(u=>String(u.username||'').replace(/^@/,'').toLowerCase()===wanted)||readAddedDirectoryContacts().find(u=>String(u.username||'').replace(/^@/,'').toLowerCase()===wanted)||(window.pulseDirectoryUsers||[]).find(u=>String(u.username||'').replace(/^@/,'').toLowerCase()===wanted);if(peer){openChat(peer.id);return}try{sessionStorage.setItem('voltraPendingDeepLink',location.pathname)}catch{}if(typeof loadUsers==='function')loadUsers().then(()=>{const match=users.find(u=>String(u.username||'').replace(/^@/,'').toLowerCase()===wanted);if(match)openChat(match.id)}).catch(()=>{})}
}
function openChat(id){if(id==='gift-upgrader-bot'){activeId=id;try{localStorage.removeItem('pulseActiveChat')}catch{}applyActiveChatBackground();$('app').classList.add('chat-open');$('welcome').classList.add('hidden');$('messages').classList.remove('hidden');$('composer').classList.add('hidden');$('peerName').textContent='@upgrader · Gift Upgrader';$('peerAvatar').textContent='⌃';$('peerStatus').textContent='Апгрейд настоящих подарков VOLTRA';$('typing').classList.add('hidden');renderList();window.pulseRenderGiftUpgraderChat?.($('messages'));return}if(id==='drop-bot'){activeId=id;try{localStorage.removeItem('pulseActiveChat')}catch{}applyActiveChatBackground();$('app').classList.add('chat-open');$('welcome').classList.add('hidden');$('messages').classList.remove('hidden');$('composer').classList.add('hidden');$('peerName').textContent='@drop · Drop';$('peerAvatar').textContent='🎁';$('peerStatus').textContent='Бесплатные косметические кейсы · без ставок';$('typing').classList.add('hidden');renderList();window.pulseRenderDropBotChat?.($('messages'));return}try{const sharePath=voltraLinkForChat(id);history.replaceState({voltraDeepLink:true},'',sharePath)}catch{}if(String(id).startsWith('mini-bot:')){activeId=id;try{localStorage.setItem('pulseActiveChat',String(id))}catch{}$('app').classList.add('chat-open');$('welcome').classList.add('hidden');$('messages').classList.remove('hidden');$('composer').classList.add('hidden');const app=(window.pulseMiniApps||[]).find(x=>x.id===String(id).slice(9));$('peerName').textContent=app?.botName||'MiniApp Bot';$('peerAvatar').textContent=app?.botIcon||'🤖';$('peerStatus').textContent='Бот · MiniApp';$('typing').classList.add('hidden');renderList();window.pulseRenderMiniBotChat?.(id,$('messages'));return}activeId=id;if(id==='favorites')messagesByChat.set('favorites',readFavorites());try{localStorage.setItem('pulseActiveChat',String(id))}catch{}applyActiveChatBackground();updateChannelActions();unreadCounts.set(id===globalKey?globalKey:(String(id).startsWith('channel:')?channelKey(id.slice(8)):dmKey(id)),0);$('app').classList.add('chat-open');$('welcome').classList.add('hidden');$('messages').classList.remove('hidden');$('composer').classList.toggle('hidden',id==='cookie-bot'||id==='crypto-bot');const peer=users.find(u=>u.id===id)||readAddedDirectoryContacts().find(u=>u.id===id)||(window.pulseDirectoryUsers||[]).find(u=>u.id===id);$('peerName').innerHTML=id==='cookie-bot'?'🍪 Печенька':(id==='crypto-bot'?'🐱 Крипто бот':(id==='favorites'?'⭐ Избранное':esc(labelFor(id))+adminBadge(peer)+giftDecor(peer)));$('peerAvatar').innerHTML=id==='cookie-bot'?'🍪':(id==='crypto-bot'?'🐱':(id==='favorites'?'⭐':(id===globalKey?'✦':avatarContent(labelFor(id),peer?.avatar))));$('peerStatus').textContent=id==='favorites'?'Локальный чат · сообщения хранятся только на этом устройстве':id==='cookie-bot'?'Мини-игра · 30 кликов = 1 Вольтрикс':(id==='crypto-bot'?'Общий кошелёк CAT · доступен всем пользователям':(id===globalKey?'Общий чат · все пользователи':(isChannel()?(channels.find(c=>c.id===activeChannelId())?.description||'Канал VOLTRA'):(peer?.online?'В сети':'Не в сети'))));$('typing').classList.add('hidden');renderList();if(id==='cookie-bot'){loadCookieStatus();return}if(id==='crypto-bot'){loadCryptoBot();return}renderMessages();if(id==='favorites')return;markCurrentRead();if(isChannel())send({t:'history',channelId:activeChannelId()});else if(id!==globalKey)send({t:'history',to:id})}
function closeMediaViewer(){const el=$('mediaViewer');if(!el)return;const v=el.querySelector('video');if(v){try{v.pause();v.removeAttribute('src');v.load()}catch{}}el.remove();document.body.classList.remove('media-viewer-open')}
