function renderCatWallet(d,target){const el=target||document.querySelector('.cat-miniapp-body');if(!el)return;const w=d.wallet,security=d.security||{configured:false};el.innerHTML='<div class="cookie-game"><div class="cookie-game-kicker">VOLTRA WALLET</div><h2>🐱 CAT Wallet</h2><p>Внутренняя валюта VOLTRA. CAT не является настоящей криптовалютой и не имеет гарантированной денежной стоимости.</p><div class="cookie-captcha" style="margin-top:12px"><b>🔐 Защита кошелька</b><p>'+(security.configured?'PIN и кодовые фразы настроены.':'Сначала создай PIN из 4 цифр и кодовые фразы для восстановления.')+'</p>'+(security.configured?'<button data-crypto-security="recover">Восстановить PIN</button>':'<button data-crypto-security="setup">Создать защиту кошелька</button>')+'</div><div class="cookie-stats"><div><small>Cat Coins</small><b>'+Number(w.cat||0).toLocaleString('ru-RU',{maximumFractionDigits:6})+' CAT</b></div><div><small>Вольтриксы</small><b>'+Number(w.vlt||0).toLocaleString('ru-RU')+' ϟ</b></div><div><small>Курс внутри VOLTRA</small><b>128 VLT = 1 CAT</b></div></div><div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:16px"><button class="primary" data-crypto-action="buy">⚡ Купить CAT</button><button data-crypto-action="sell">↩️ Обменять CAT</button><button data-crypto-action="send">📨 Перевести CAT</button><button data-crypto-action="refresh">🔄 Обновить</button></div><h3 style="margin-top:20px">Последние операции</h3>'+(d.history&&d.history.length?'<div class="cookie-stats">'+d.history.slice(0,8).map(x=>'<div><small>'+esc(x.type==='buy'?'Покупка':x.type==='sell'?'Обмен':'Перевод')+' · '+new Date(x.at).toLocaleString('ru-RU')+'</small><b>'+Number(x.cat||0).toLocaleString('ru-RU',{maximumFractionDigits:6})+' CAT</b></div>').join('')+'</div>':'<p class="muted">Операций пока нет.</p>')+'</div>'}
async function runCryptoAction(action){try{if(action==='refresh'){await loadCryptoBot(document.querySelector('.cat-miniapp-body')||undefined);return}const security=await fetch('/api/catcoin',{cache:'no-store',credentials:'same-origin'}).then(r=>r.json());if(!security.security?.configured){toast('Сначала создай защиту кошелька');await runCryptoSecurity('setup');return}showCatPinPad(action==='buy'?'Подтверждение покупки CAT':action==='sell'?'Подтверждение обмена CAT':'Подтверждение перевода CAT','Введи PIN кошелька для подтверждения операции',async pin=>{const layer=document.createElement('div');layer.className='wallet-security-overlay';layer.innerHTML='<form class="wallet-security-card"><div class="wallet-security-top"><span class="wallet-security-icon">ϟ</span><button type="button" class="wallet-security-close" aria-label="Закрыть">×</button></div><div class="cookie-game-kicker">VOLTRA WALLET · CAT</div><h2>'+(action==='buy'?'Купить CAT':action==='sell'?'Обменять CAT':'Перевести CAT')+'</h2><p class="wallet-security-sub">'+(action==='buy'?'Укажи любое количество Вольтриксов, можно с десятыми. Курс: 128 VLT = 1 CAT.':action==='sell'?'Укажи количество CAT для обмена на Вольтриксы.':'Укажи количество CAT и ник получателя.')+'</p><label>Количество '+(action==='buy'?'Вольтриксов (VLT)':'CAT')+' <input name="amount" type="number" min="'+(action==='buy'?'0.1':'1')+'" max="'+(action==='buy'?'1000000000000':'1000000000000')+'" step="'+(action==='buy'?'0.1':'1')+'" inputmode="decimal" placeholder="'+(action==='buy'?'Например, 12.5': 'Например, 1')+'" required></label>'+(action==='send'?'<label>Ник получателя <input name="toUsername" maxlength="40" autocomplete="off" placeholder="@username" required></label>':'')+'<p class="wallet-security-status" role="status"></p><button class="primary wallet-security-submit" type="submit">Подтвердить</button></form>';document.body.append(layer);layer.querySelector('.wallet-security-close').onclick=()=>layer.remove();layer.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,btn=f.querySelector('button[type=submit]'),payload={action,amount:Number(f.elements.amount.value),pin};if(action==='send')payload.toUsername=f.elements.toUsername.value.trim();btn.disabled=true;try{const r=await fetch('/api/catcoin/action',{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)}),d=await r.json();if(!r.ok)throw new Error(d.error||'Операция не выполнена');layer.remove();toast(d.message||'Готово');await loadCryptoBot(document.querySelector('.cat-miniapp-body')||undefined)}catch(err){f.querySelector('.wallet-security-status').textContent=err.message||'Ошибка';btn.disabled=false}}})}catch(e){toast(e.message||'Ошибка Крипто бота')}}
async function openCatMiniApp(){if(document.querySelector('.cat-miniapp'))return;const host=document.createElement('div');host.className='cat-miniapp';host.innerHTML='<div class="cat-miniapp-head"><div><small>VOLTRA MINI APP</small><b>🐱 CAT Wallet</b></div><button type="button" data-cat-mini-close aria-label="Закрыть">×</button></div><div class="cat-miniapp-body"><p class="cat-miniapp-loading">Проверяем защиту кошелька…</p></div>';document.body.append(host);const body=host.querySelector('.cat-miniapp-body');host.addEventListener('click',e=>{if(e.target.closest('[data-cat-mini-close]')){host.remove();return}if(e.target.closest('[data-cat-mini-home]')){body.scrollTo({top:0,behavior:'smooth'});return}const sec=e.target.closest('[data-crypto-security]');if(sec){runCryptoSecurity(sec.dataset.cryptoSecurity);return}const act=e.target.closest('[data-crypto-action]');if(act){runCryptoAction(act.dataset.cryptoAction);return}});try{const r=await fetch('/api/catcoin',{cache:'no-store',credentials:'same-origin'}),d=await r.json();if(!r.ok)throw new Error(d.error||'Не удалось загрузить кошелёк');if(d.security?.configured){body.innerHTML='<p class="cat-miniapp-loading">Ожидаем подтверждение PIN…</p>';showCatPinPad('Вход в CAT Wallet','Для каждого входа требуется PIN',async pin=>{try{const vr=await fetch('/api/catcoin/security/verify',{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',body:JSON.stringify({pin})}),vd=await vr.json();if(!vr.ok)throw new Error(vd.error||'PIN не принят');if(host.isConnected)await loadCryptoBot(body)}catch(err){toast(err.message||'Не удалось подтвердить PIN');host.remove()}})}else{await loadCryptoBot(body)}}catch(e){body.innerHTML='<div class="cookie-game"><h2>CAT Wallet</h2><p>'+esc(e.message||'Ошибка загрузки')+'</p><button type="button" data-cat-mini-close>Закрыть</button></div>'}}
document.addEventListener('click',e=>{const open=e.target.closest('[data-crypto-open]');if(open){e.preventDefault();e.stopPropagation();openCatMiniApp();return}const sec=e.target.closest('[data-crypto-security]');if(sec&&!document.querySelector('.cat-miniapp')){e.preventDefault();e.stopPropagation();runCryptoSecurity(sec.dataset.cryptoSecurity)}},true);
function showCatPinPad(title,subtitle,onComplete){
 const layer=document.createElement('div');
 layer.className='cat-pin-overlay';
 layer.innerHTML='<div class="cat-pin-screen" role="dialog" aria-modal="true" aria-label="PIN-код"><div class="cat-pin-top"><span>🔐</span><button type="button" data-pin-close aria-label="Закрыть">×</button></div><div class="cat-pin-title">'+esc(title)+'</div><div class="cat-pin-sub"></div><div class="cat-pin-dots" aria-label="Введено цифр"><i></i><i></i><i></i><i></i></div><div class="cat-pin-pad">'+['1','2','3','4','5','6','7','8','9','back','0','ok'].map(k=>'<button type="button" data-pin-key="'+k+'" aria-label="'+(k==='back'?'Удалить последнюю цифру':k==='ok'?'Подтвердить PIN':k)+'">'+(k==='back'?'⌫':k==='ok'?'✓':k)+'</button>').join('')+'</div><div class="cat-pin-error" aria-live="polite"></div></div>';
 document.body.appendChild(layer);
 let pin='',finished=false;
 const dots=layer.querySelectorAll('.cat-pin-dots i'),err=layer.querySelector('.cat-pin-error'),sub=layer.querySelector('.cat-pin-sub');
 const update=()=>{dots.forEach((d,i)=>d.classList.toggle('filled',i<pin.length));sub.textContent=(subtitle||'Введите 4-значный PIN-код')+' · '+pin.length+'/4'};
 const cleanup=()=>{document.removeEventListener('keydown',keyHandler,true);layer.remove()};
 const submit=()=>{if(pin.length!==4){err.textContent='Введите все 4 цифры';return}if(finished)return;finished=true;const value=pin;cleanup();onComplete(value)};
 const press=k=>{if(finished)return;if(k==='back')pin=pin.slice(0,-1);else if(k==='ok'){submit();return}else if(/^\d$/.test(k)&&pin.length<4)pin+=k;err.textContent='';update();if(pin.length===4)err.textContent='Нажмите ✓ для подтверждения'};
 const keyHandler=e=>{if(!layer.isConnected)return;if(/^\d$/.test(e.key)){e.preventDefault();e.stopImmediatePropagation();press(e.key)}else if(e.key==='Backspace'||e.key==='Delete'){e.preventDefault();e.stopImmediatePropagation();press('back')}else if(e.key==='Enter'){e.preventDefault();e.stopImmediatePropagation();press('ok')}else if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();cleanup()}};
 layer.querySelectorAll('[data-pin-key]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();press(b.dataset.pinKey)}));
 layer.querySelector('[data-pin-close]').addEventListener('click',e=>{e.preventDefault();e.stopPropagation();cleanup()});
 document.addEventListener('keydown',keyHandler,true);
 update();
 return layer
}

